// Package main: end-to-end tests for the two modes the hooks invoke.
//
// These drive run() against a real repository rather than calling the
// individual rules, so they prove the wiring as well as the rules: that
// staged content actually reaches the checks, that a generated file is
// actually skipped, and that a binary file does not crash the walk.
package main

import (
	"os"
	"path/filepath"
	"testing"
)

func TestRunOnStagedContentFindsAForbiddenCharacter(t *testing.T) {
	newRepo(t)
	write(t, "docs/note.md", "a sentence "+string(emDash)+" and its aside\n")

	findings, err := run("")
	if err != nil {
		t.Fatalf("run: %v", err)
	}
	if !hasRule(findings, SeverityFail, "em dash") {
		t.Errorf("run did not reach the dash rule: %+v", findings)
	}
}

func TestRunOnStagedContentIsSilentOnACleanCommit(t *testing.T) {
	newRepo(t)
	write(t, "internal/x/x.go", wellFormedSource)
	write(t, "README.md", "# a project\n\nIt does a thing.\n")

	findings, err := run("")
	if err != nil {
		t.Fatalf("run: %v", err)
	}
	if len(findings) != 0 {
		t.Errorf("run reported %d findings against a clean commit: %+v", len(findings), findings)
	}
}

func TestRunSkipsGeneratedGoButStillReadsItsText(t *testing.T) {
	// A generated file is not asked for a hand-written docstring. It is
	// still read for a forbidden character, because such a character in a
	// generated file is real and shipped; the fix is in the source.
	newRepo(t)
	write(t, "internal/ent/thing.go",
		"// Code generated by ent, DO NOT EDIT.\n\npackage ent\n\nfunc  F()  {}\n")

	findings, err := run("")
	if err != nil {
		t.Fatalf("run: %v", err)
	}
	if hasRule(findings, SeverityFail, "gofmt") {
		t.Error("applied the gofmt rule to generated code")
	}
	if hasRule(findings, SeverityFail, "docstring") {
		t.Error("demanded a docstring from generated code")
	}
}

func TestRunSkipsABinaryFile(t *testing.T) {
	newRepo(t)
	if err := os.MkdirAll("web/static", 0o750); err != nil {
		t.Fatalf("creating web/static: %v", err)
	}
	blob := []byte{0x89, 'P', 'N', 'G', 0x00, 0x1a, 0x0a, 0x00}
	if err := os.WriteFile(filepath.Join("web", "static", "logo.png"), blob, 0o600); err != nil {
		t.Fatalf("writing the blob: %v", err)
	}
	if out, err := gitCombined("add", "--", "web/static/logo.png"); err != nil {
		t.Fatalf("git add: %v: %s", err, out)
	}

	findings, err := run("")
	if err != nil {
		t.Fatalf("run: %v", err)
	}
	if len(findings) != 0 {
		t.Errorf("judged a binary file: %+v", findings)
	}
}

func TestRunOnAnEmptyIndexReportsNothing(t *testing.T) {
	newRepo(t)
	findings, err := run("")
	if err != nil {
		t.Fatalf("run: %v", err)
	}
	if len(findings) != 0 {
		t.Errorf("reported %d findings with nothing staged", len(findings))
	}
}

func TestRunInMessageModeReadsTheFile(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "COMMIT_EDITMSG")
	if err := os.WriteFile(path, []byte("Add a thing\n"), 0o600); err != nil {
		t.Fatalf("writing the message file: %v", err)
	}
	findings, err := run(path)
	if err != nil {
		t.Fatalf("run: %v", err)
	}
	if !hasRule(findings, SeverityFail, "conventional") {
		t.Errorf("message mode did not reach the subject rule: %+v", findings)
	}
}

func TestRunInMessageModeReportsAnUnreadableFile(t *testing.T) {
	// A gate that cannot read its input has not passed. Returning no
	// findings here would let every future failure of the tool go
	// unnoticed.
	if _, err := run(filepath.Join(t.TempDir(), "does-not-exist")); err == nil {
		t.Error("run accepted a commit message file it could not read")
	}
}

func TestRunReportsAGitFailureRatherThanPassing(t *testing.T) {
	// Outside a repository there is no index to read, and the answer must
	// be an error rather than an empty, reassuring finding list.
	dir := t.TempDir()
	original, err := os.Getwd()
	if err != nil {
		t.Fatalf("reading the working directory: %v", err)
	}
	if err := os.Chdir(dir); err != nil {
		t.Fatalf("entering the temporary directory: %v", err)
	}
	t.Cleanup(func() {
		if err := os.Chdir(original); err != nil {
			t.Fatalf("leaving the temporary directory: %v", err)
		}
	})

	// A temporary directory can sit inside another repository's tree, in
	// which case git answers normally and there is nothing to assert.
	if _, err := git("rev-parse", "--is-inside-work-tree"); err == nil {
		t.Skip("the temporary directory is inside a git repository, so there is no failure to observe")
	}
	if _, err := run(""); err == nil {
		t.Error("run reported success outside a git repository")
	}
}
